{
  "summary": "The proposal keeps the 99.5% availability target (to avoid breaking the Service Credit table), revises clause 2.2 to allow termination for any service level failure with a 30-day cure period and no once-per-12-month limit, and adds a definition for 'Scheduled Maintenance' to remove ambiguity.",
  "wording": [
    {
      "paragraph_id": "b8",
      "text": "<now>Harbourline shall make the Services available 99.5% of the time in each calendar month, excluding Scheduled Maintenance.</now>"
   ,
      "why": "The 99.9% change is not adopted because it would break the Service Credit table (no tier for 99.5%-99.9%). The original 99.5% target remains. The undefined 'Scheduled Maintenance' is addressed by adding a definition in clause 1."
    },
    {
      "paragraph_id": "b9",
      "text": "<now>If Harbourline fails to meet a service level, the Customer may terminate on notice if the failure is not remedied within thirty (30) days. This right may be exercised on each occasion of such failure.</now>",
      "why": "Aligns the cure period with the approved 30-day standard and removes the once-per-12-month restriction, consistent with the approved 'Termination for breach' clause."
    },
    {
      "paragraph_id": "b5",
      "text": "<now>\"Scheduled Maintenance\" means any maintenance of the Services that Harbourline notifies the Customer of at least 48 hours in advance and that is performed outside the hours of 00:00 to 06:00 UK time.</now>",
      "why": "Defines 'Scheduled Maintenance' to remove ambiguity, as flagged in the language finding."
    }
  ],
  "their_changes": [
    {
      "paragraph_id": "b8",
      "change_index": 1,
      "decision": "reject",
      "why": "The 99.9% change would break the Service Credit table (no tier for 99.5%-99.9%), so the original 99.5% target is kept."
    },
    {
      "paragraph_id": "b9",
      "change_index": 1,
      "decision": "accept",
      "why": "Adopts the suggested wording to align the cure period with 30 days and remove the once-per-12-month limit."
    },
    {
      "paragraph_id": "b8",
      "change_index": 2,
      "decision": "accept",
      "why": "The undefined 'Scheduled Maintenance' is addressed by adding a definition in clause 1."
    }
  ],
  "comment_to_them": "We have kept the 99.5% availability target to preserve the Service Credit structure, revised the termination right to a 30-day cure period with no frequency limit, and added a definition for 'Scheduled Maintenance' to avoid ambiguity.",
  "injection_suspected": false,
  "injection_notes": ""
